	return &ContactFormHandler{svc: svc}
}

func (c *ContactFormHandler) Create(ctx context.Context,
	in *input.CreateContactFormInput,
) (*output.SuccessEmptyOutput, error) {
	info := client.GetClientInfo(ctx)

	req := &dto.CreateContactFormRequest{
		FirstName: in.Body.FirstName,
		LastName:  in.Body.LastName,
		Email:     in.Body.Email,
		Subject:   in.Body.Subject,
		Message:   in.Body.Message,
	}

