		req.IPAddr = info.IP
		req.UserAgent = info.UserAgent
	}

	err := c.svc.Create(ctx, req)
	if err != nil {
		return nil, output.NewErrorOutput(err)
	}

	return output.NewSuccessEmptyOutput(), nil
}

