package waitlist

import (
	"context"

	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist/repository"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist/service"
	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/InfraFund-net7/backpro/pkg/logger"
)

var _ service.WaitListService = (*Waitlist)(nil)

type Waitlist struct {
	waitListRepo repository.WaitlistRepo
	logger       *logger.SubLogger
}

func NewWaitlistService(waitListRepo repository.WaitlistRepo) *Waitlist {
	return &Waitlist{
		waitListRepo: waitListRepo,
		logger:       logger.NewBusinessLogger("waitlist"),
	}
}

func (*Waitlist) String() string {
	return "Waitlist"
}

func (w *Waitlist) Create(ctx context.Context, email shared.Email) error {
	exists, err := w.waitListRepo.EmailExists(ctx, email)
	if err != nil {
		w.logger.Error("failed to check if email exists", "email", email, "error", err)

		return errs.NewAppError(errs.Database, "failed to check if email exists", 500).WithError(err)
	}

	if exists {
		return waitlist.ErrEmailExists
	}

	if err := w.waitListRepo.Create(ctx, email); err != nil {
		w.logger.Error("failed to create waitlist entry", "email", email, "error", err)

		return errs.NewAppError(errs.Database, "failed to create waitlist entry", 500).WithError(err)
	}

	return nil
}

