	"github.com/InfraFund-net7/backpro/internal/domain/non_resident_waitlist/repository"
	"github.com/InfraFund-net7/backpro/internal/domain/non_resident_waitlist/service"
	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/InfraFund-net7/backpro/pkg/logger"
)

var _ service.NonResidentWaitListService = (*NonResidentWaitlistService)(nil)

type NonResidentWaitlistService struct {
	nonResidentWaitlistRepo repository.NonResidentWaitListRepo
	logger                  *logger.SubLogger
}

func NewNonResidentWaitlistService(
	nonResidentWaitlistRepo repository.NonResidentWaitListRepo,
) *NonResidentWaitlistService {
	return &NonResidentWaitlistService{
		nonResidentWaitlistRepo: nonResidentWaitlistRepo,
		logger:                  logger.NewBusinessLogger("non_resident_waitlist"),
	}
}

func (n *NonResidentWaitlistService) CreateIndividualForm(ctx context.Context, req *dto.CreateIndividualFormReq) error {
	err := n.nonResidentWaitlistRepo.Create(ctx, &entity.NonResidentWaitList{
		FirstName: req.FirstName,
		LastName:  req.LastName,
		Email:     req.Email.String(),
		Type:      object.NonResidentTypeIndividual,
		CountryID: req.CountryID,
	})
	if err != nil {
		if errs.IsDuplicateKeyError(err, "non_resident_waitlists_email_key") {
			return errs.NewAppError(errs.Conflict, "email already exists", 409).WithError(err)
		}

		if errs.IsForeignKeyError(err, "non_resident_waitlists_country_id_fkey") {
			return errs.NewAppError(errs.BadRequest, "invalid country ID", 400).WithError(err)
		}

		n.logger.Error("failed to create individual form", "error", err, "email", req.Email)

		return errs.NewAppError(errs.Database, "failed to create individual form", 500).WithError(err)
	}

	return nil
}

func (n *NonResidentWaitlistService) CreateCompanyForm(ctx context.Context, req *dto.CreateCompanyFormReq) error {
	err := n.nonResidentWaitlistRepo.Create(ctx, &entity.NonResidentWaitList{
		FirstName:   req.FirstName,
		LastName:    req.LastName,
		CompanyName: req.CompanyName,
		Email:       req.Email.String(),
		Type:        object.NonResidentTypeCompany,
		CountryID:   req.CountryID,
	})
	if err != nil {
		if errs.IsDuplicateKeyError(err, "non_resident_waitlists_email_key") {
			return errs.NewAppError(errs.Conflict, "email already exists", 409).WithError(err)
		}

		if errs.IsForeignKeyError(err, "non_resident_waitlists_country_id_fkey") {
			return errs.NewAppError(errs.BadRequest, "invalid country ID", 400).WithError(err)
		}

		n.logger.Error("failed to create company form", "error", err, "email", req.Email)

		return errs.NewAppError(errs.Database, "failed to create company form", 500).WithError(err)
	}

	return nil
}

