package errs

import (
	"fmt"

	"github.com/danielgtaylor/huma/v2"
)

// AppError represents a structured application error.
type AppError struct {
	Code       ErrorCode      `json:"-"`
	Message    string         `json:"message" doc:"Detailed error message"`
	Details    map[string]any `json:"details,omitempty" doc:"Additional error context"`
	StatusCode int            `json:"-"`
	Err        error          `json:"-"`
}

func (e *AppError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("%s: %s (underlying: %v)", e.Code, e.Message, e.Err)
	}

	return fmt.Sprintf("%s: %s", e.Code, e.Message)
}

func (e *AppError) Unwrap() error {
	return e.Err
}

// WithDetails adds additional context to the error.
func (e *AppError) WithDetails(key string, value any) *AppError {
	if e.Details == nil {
		e.Details = make(map[string]any)
	}
	e.Details[key] = value

	return e
}

// WithError wraps an underlying error.
func (e *AppError) WithError(err error) *AppError {
	e.Err = err

	return e
}

// NewAppError creates a new application error.
func NewAppError(code ErrorCode, message string, statusCode int) *AppError {
	return &AppError{
		Code:       code,
		Message:    message,
		StatusCode: statusCode,
	}
}

func NewNotFoundError(resource string) *AppError {
	err := *ErrNotFound
	err.Message = fmt.Sprintf("%s not found", resource)

	return &err
}

func NewUnauthorizedError(message string) *AppError {
	err := *ErrUnauthorized
	err.Message = message

	return &err
}

func NewConflictError(message string) *AppError {
	err := *ErrConflict
	err.Message = message

	return &err
}

func NewInternalError(message string) *AppError {
	err := *ErrInternal
	err.Message = message

	return &err
}

func (e *AppError) ToHuma() error {
	model := &huma.ErrorModel{
		Title:  e.Code.String(),
		Detail: e.Message,
		Status: e.StatusCode,
		Errors: make([]*huma.ErrorDetail, 0),
	}

	for k, v := range e.Details {
		model.Errors = append(model.Errors, &huma.ErrorDetail{
			Message: k,
			Value:   v,
		})
	}

	return model
}

package errs

import (
	"errors"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// IsConstraintError checks if an error is a PostgreSQL constraint violation
func IsConstraintError(err error) bool {
	var pgErr *pgconn.PgError

	return errors.As(err, &pgErr) && pgErr.ConstraintName != ""
}

func IsNotFoundError(err error) bool {
	return errors.Is(err, pgx.ErrNoRows)
}

// GetConstraintName extracts the constraint name from a PostgreSQL error
func GetConstraintName(err error) string {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		return pgErr.ConstraintName
	}

	return ""
}

// IsDuplicateKeyError checks if the error is a PostgreSQL duplicate key constraint violation.
func IsDuplicateKeyError(err error, constraint string) bool {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		// 23505 is the PostgreSQL error code for unique_violation
		return pgErr.Code == "23505" && pgErr.ConstraintName == constraint
	}

	return false
}

// IsForeignKeyError checks if the error is a PostgreSQL foreign key constraint violation.
func IsForeignKeyError(err error, constraint string) bool {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		// 23503 is the PostgreSQL error code for foreign_key_violation
		return pgErr.Code == "23503" && pgErr.ConstraintName == constraint
	}

	return false
}

// GetPgErrorCode extracts the PostgreSQL error code from an error.
func GetPgErrorCode(err error) string {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		return pgErr.Code
	}

	return ""
}

func IsErrConstraint(err error, constraintName string) bool {
	return GetConstraintName(err) == constraintName
}

package middleware

import (
	"github.com/danielgtaylor/huma/v2"
	"github.com/gofiber/fiber/v2"
	"github.com/ja7ad/captcha"
)

const recaptchaHeaderKey = "X-Captcha-Token"

func Recaptcha(api huma.API, rcap captcha.Captcha) func(ctx huma.Context, next func(huma.Context)) {
	return func(ctx huma.Context, next func(huma.Context)) {
		if rcap == nil {
			next(ctx)

			return
		}

		challengeKey := extractChallengeKeyFromHeader(ctx)
		if challengeKey == "" {
			_ = huma.WriteErr(api, ctx, fiber.StatusBadRequest, "missing recaptcha challenge key in header")

			return
		}

		ok, err := rcap.Validate(ctx.Context(), challengeKey, ctx.RemoteAddr())
		if err != nil {
			_ = huma.WriteErr(api, ctx, fiber.StatusInternalServerError, "failed to verify captcha", err)

			return
		}

		if !ok {
			_ = huma.WriteErr(api, ctx, fiber.StatusUnauthorized, "captcha verification failed", err)

			return
		}

		next(ctx)
	}
}

func extractChallengeKeyFromHeader(ctx huma.Context) string {
	token := ctx.Header(recaptchaHeaderKey)

	return token
}

package middleware

import (
	"net"
	"strings"

	"github.com/InfraFund-net7/backpro/internal/common/types/client"
	"github.com/InfraFund-net7/backpro/internal/common/types/key"
	"github.com/danielgtaylor/huma/v2"
	"github.com/mileusna/useragent"
)

func ClientInfo(ctx huma.Context, next func(ctx huma.Context)) {
	ip := getClientIP(ctx)
	userAgentStr := ctx.Header("User-Agent")
	ua := useragent.Parse(userAgentStr)

	device := "desktop"
	if ua.Mobile {
		device = "mobile"
	} else if ua.Tablet {
		device = "tablet"
	} else if ua.Bot {
		device = "bot"
	}

	// Determine platform (OS-based, not device-based)
	platform := getOS(&ua)

	// Create user context
	info := &client.Info{
		IP:        ip,
		UserAgent: userAgentStr,
		Platform:  platform,
		Device:    device,
		Browser:   getBrowser(&ua),
	}

	ctx = huma.WithValue(ctx, key.ClientInfoKey, info)

	next(ctx)
}

// getClientIP extracts the real client IP from headers or RemoteAddr
func getClientIP(ctx huma.Context) string {
	// Priority order:
	// 1. X-Real-IP (set by nginx/load balancer)
	// 2. X-Forwarded-For (first IP in the chain)
	// 3. RemoteAddr (fallback)

	if ip := ctx.Header("X-Real-IP"); ip != "" {
		return stripPort(ip)
	}

	if xff := ctx.Header("X-Forwarded-For"); xff != "" {
		// X-Forwarded-For can be: "client, proxy1, proxy2"
		// Take the first IP (original client)
		ips := strings.Split(xff, ",")
		if len(ips) > 0 {
			return strings.TrimSpace(ips[0])
		}
	}

	// Fallback to RemoteAddr and strip port
	return stripPort(ctx.RemoteAddr())
}

// stripPort removes port from IP address (handles both IPv4 and IPv6)
func stripPort(addr string) string {
	// For IPv6: [::1]:8080 or [2001:db8::1]:8080
	// For IPv4: 127.0.0.1:8080
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		// If no port, return as-is
		return addr
	}

	return host
}

// getOS returns a formatted OS string.
func getOS(ua *useragent.UserAgent) string {
	if ua.OS != "" {
		os := ua.OS
		if ua.OSVersion != "" {
			os += " " + ua.OSVersion
		}

		return os
	}

	// Return a simple unknown if OS is not detected
	return "unknown"
}

// getBrowser returns a formatted browser string.
func getBrowser(ua *useragent.UserAgent) string {
	browser := ua.Name
	if browser == "" {
		browser = "unknown"
	}

	if ua.Version != "" {
		browser += " " + ua.Version
	}

	return strings.TrimSpace(browser)
}

