package integration

import (
	"context"
	"testing"

	"github.com/InfraFund-net7/backpro/internal/application/waitlist"
	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist/repository"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist/service"
	"github.com/InfraFund-net7/backpro/internal/infrastructure/persistence/postgres"
	"github.com/stretchr/testify/suite"
)

type WaitListIntegration struct {
	integration
	svc  service.WaitListService
	repo repository.WaitlistRepo
}

func (w *WaitListIntegration) SetupTest() {
	w.integration.SetupTest()

	w.repo = postgres.NewWaitlistRepo(w.DB)
	w.svc = waitlist.NewWaitlistService(w.repo)
}

func (w *WaitListIntegration) TestCreate() {
	email := shared.NewEmail("test@suite.com")

	err := w.svc.Create(context.Background(), email)
	w.NoError(err)

	exists, err := w.repo.EmailExists(context.Background(), email)
	w.NoError(err)
	w.True(exists)
}

func TestWaitlistRepoSuite(t *testing.T) {
	suite.Run(t, new(WaitListIntegration))
}

package integration

import (
	"context"
	"testing"

	contactform "github.com/InfraFund-net7/backpro/internal/application/contact_form"
	"github.com/InfraFund-net7/backpro/internal/application/contact_form/dto"
	"github.com/InfraFund-net7/backpro/internal/domain/contact_form/repository"
	"github.com/InfraFund-net7/backpro/internal/domain/contact_form/service"
	"github.com/InfraFund-net7/backpro/internal/infrastructure/persistence/postgres"
	"github.com/stretchr/testify/require"
	"github.com/stretchr/testify/suite"
)

type ContactFormIntegration struct {
	integration
	svc  service.ContactFormService
	repo repository.ContactFormRepo
}

func (w *ContactFormIntegration) SetupTest() {
	w.integration.SetupTest()

	w.repo = postgres.NewContactFormRepo(w.DB)
	w.svc = contactform.NewContactFormService(w.repo, &contactform.Config{
		Enabled: false,
	})
}

func (w *ContactFormIntegration) TestCreate() {
	tests := []struct {
		name      string
		firstName string
		lastName  string
		email     string
		subject   string
		message   string
		exceptErr bool
	}{
		{
			name:      "valid contact form",
			firstName: "Alice",
			lastName:  "Smith",
			email:     "alice@gmail.com",
			subject:   "Inquiry about services",
			message:   "I would like to know more about your services.",
			exceptErr: false,
		},
	}

	for _, tt := range tests {
		w.T().Run(tt.name, func(t *testing.T) {
			req := &dto.CreateContactFormRequest{
				FirstName: tt.firstName,
				LastName:  tt.lastName,
				Email:     tt.email,
				Subject:   tt.subject,
				Message:   tt.message,
			}

			err := w.svc.Create(context.Background(), req)

			if tt.exceptErr {
				require.Error(t, err)
			} else {
				require.NoError(t, err)
			}
		})
	}
}

func TestContactFormRepoSuite(t *testing.T) {
	suite.Run(t, new(ContactFormIntegration))
}

