import (
	"context"
	"testing"

	nonresidentwaitlist "github.com/InfraFund-net7/backpro/internal/application/non_resident_waitlist"
	"github.com/InfraFund-net7/backpro/internal/application/non_resident_waitlist/dto"
	"github.com/InfraFund-net7/backpro/internal/domain/non_resident_waitlist/repository"
	"github.com/InfraFund-net7/backpro/internal/domain/non_resident_waitlist/service"
	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	"github.com/InfraFund-net7/backpro/internal/infrastructure/persistence/postgres"
	"github.com/stretchr/testify/suite"
)

type NonResidentWaitlistIntegration struct {
	integration
	svc  service.NonResidentWaitListService
	repo repository.NonResidentWaitListRepo
}

func (n *NonResidentWaitlistIntegration) SetupTest() {
	n.integration.SetupTest()

	n.repo = postgres.NewNonResidentWaitlistRepo(n.DB)
	n.svc = nonresidentwaitlist.NewNonResidentWaitlistService(n.repo)
}

func (n *NonResidentWaitlistIntegration) ctx() context.Context {
	return context.Background()
}

func (n *NonResidentWaitlistIntegration) TestCreateIndividualForm() {
	tests := []struct {
		name      string
		firstName string
		lastName  string
		email     string
		countryID int32
		setup     func()
		assertion func(err error)
	}{
		{
			name:      "valid",
			firstName: "Alice",
			lastName:  "Smith",
			email:     "alice1@example.com",
			countryID: 1,
			setup:     func() {},
			assertion: func(err error) { require := n.Require(); require.NoError(err) },
		},
		{
			name:      "duplicate email",
			firstName: "Bob",
			lastName:  "Smith",
			email:     "duplicate@example.com",
			countryID: 1,
			setup: func() {
				err := n.svc.CreateIndividualForm(n.ctx(), &dto.CreateIndividualFormReq{
					FirstName: "Bob",
					LastName:  "Smith",
					Email:     shared.NewEmail("duplicate@example.com"),
					CountryID: 1,
				})
				n.Require().NoError(err)
			},
			assertion: func(err error) {
				require := n.Require()
				require.Error(err)
				require.Contains(err.Error(), "email already exists")
			},
		},
		{
			name:      "country id invalid",
			firstName: "Carol",
			lastName:  "Smith",
			email:     "carol@example.com",
			countryID: 999999,
			setup:     func() {},
			assertion: func(err error) {
				require := n.Require()
				require.Error(err)
				require.Contains(err.Error(), "invalid country ID")
			},
		},
		{
			name:      "unknown database error",
			firstName: "Dave",
			lastName:  "Smith",
			email:     "dave@example.com",
			countryID: 1,
			setup: func() {
				// Simulate by closing DB connection
				n.DB.Pool().Close()
			},
			assertion: func(err error) {
				require := n.Require()
				require.Error(err)
				require.Contains(err.Error(), "failed to create individual form")
			},
		},
	}

