			firstName:   "Alice",
			lastName:    "Smith",
			email:       "alice@gmail.com",
			countryID:   1,
			companyName: "Acme Corp",
			setup:       func() {},
			assertion:   func(err error) { require := n.Require(); require.NoError(err) },
		},
		{
