			firstName:   "Bob",
			lastName:    "Smith",
			email:       "duplicate@company.com",
			countryID:   1,
			companyName: "Acme Corp",
			setup: func() {
				err := n.svc.CreateCompanyForm(n.ctx(), &dto.CreateCompanyFormReq{
					FirstName:   "Bob",
					LastName:    "Smith",
					CompanyName: "Acme Corp",
					Email:       shared.NewEmail("duplicate@company.com"),
					CountryID:   1,
				})
				n.Require().NoError(err)
			},
			assertion: func(err error) {
				require := n.Require()
				require.Error(err)
				require.Contains(err.Error(), "email already exists")
			},
		},
		{
			name:        "country id invalid",
			firstName:   "Carol",
			lastName:    "Smith",
			email:       "carol@company.com",
