type Config struct {
	Development               bool          `koanf:"-"`
	Port                      string        `koanf:"port"`
	Debug                     bool          `koanf:"debug"`
	BodyLimit                 int           `koanf:"body_limit"`
	Concurrency               int           `koanf:"concurrency"`
	ReadTimeout               time.Duration `koanf:"read_timeout"`
	WriteTimeout              time.Duration `koanf:"write_timeout"`
	IdleTimeout               time.Duration `koanf:"idle_timeout"`
	StrictRouting             bool          `koanf:"strict_routing"`
	CaseSensitive             bool          `koanf:"case_sensitive"`
	ReduceMemoryUsage         bool          `koanf:"reduce_memory_usage"`
	DisableStartupMessage     bool          `koanf:"disable_startup_message"`
	EnableHealthCheck         bool          `koanf:"enable_health_check"`
	EnableReadinessCheck      bool          `koanf:"enable_readiness_check"`
	EnableHelmet              bool          `koanf:"enable_helmet"`
	EnablePProf               bool          `koanf:"enable_pprof"`
	EnableCompressRequestBody bool          `koanf:"enable_compress_request_body"`
	EnableMetricsMonitoring   bool          `koanf:"enable_metrics_monitoring"`
	Cors                      *CORS         `koanf:"cors"`
	RateLimit                 *RateLimit    `koanf:"rate_limit"`
	Recaptcha                 *Recaptcha    `koanf:"recaptcha"`
	CookieEncryptionSecretKey string        `koanf:"cookie_encryption_secret_key"`
	CookieSameSite            string        `koanf:"cookie_same_site"`
	CookieDomain              string        `koanf:"cookie_domain"`
}

type Recaptcha struct {
	GoogleSecret     string `koanf:"google_secret"`
	HCaptchaSecret   string `koanf:"hcaptcha_secret"`
	CloudflareSecret string `koanf:"cloudflare_secret"`
}

type CORS struct {
	AllowOrigins []string `koanf:"allow_origins"`
	AllowMethods []string `koanf:"allow_methods"`
	AllowHeaders []string `koanf:"allow_headers"`
}

type RateLimit struct {
	MaxRequests int           `koanf:"max_requests"`
	Expiration  time.Duration `koanf:"expiration"`
}

func DefaultConfig() *Config {
	return &Config{
		Port:                      "8080",
		Debug:                     false,
		BodyLimit:                 10 * 1024 * 1024,
		Concurrency:               256 * 1024,
		ReadTimeout:               15 * time.Second,
		WriteTimeout:              15 * time.Second,
		IdleTimeout:               60 * time.Second,
		StrictRouting:             true,
		CaseSensitive:             false,
		ReduceMemoryUsage:         true,
		DisableStartupMessage:     true,
		EnableHealthCheck:         true,
		EnableReadinessCheck:      false,
		EnableHelmet:              false,
		EnablePProf:               false,
		EnableCompressRequestBody: false,
		EnableMetricsMonitoring:   false,
		Cors: &CORS{
			AllowOrigins: []string{"http://localhost:3000", "http://127.0.0.1:3000"},
			AllowMethods: []string{"GET", "POST", "PUT", "DELETE", "OPTIONS", "PATCH"},
			AllowHeaders: []string{"Origin", "Content-Type", "Accept", "Authorization"},
		},
		RateLimit: &RateLimit{
			MaxRequests: 1000,
			Expiration:  1 * time.Minute,
		},
		Recaptcha:      &Recaptcha{},
		CookieSameSite: "lax",
	}
}

func (c *Config) BasicCheck() error {
	if c.Cors == nil {
		return errors.New("rest cors config is required")
	}

	c.Cors.AllowOrigins = normalizeStringSlice(c.Cors.AllowOrigins)
	c.Cors.AllowMethods = normalizeStringSlice(c.Cors.AllowMethods)
	c.Cors.AllowHeaders = normalizeStringSlice(c.Cors.AllowHeaders)
	c.CookieSameSite = strings.ToLower(strings.TrimSpace(c.CookieSameSite))
	c.CookieDomain = strings.TrimSpace(c.CookieDomain)
	c.CookieEncryptionSecretKey = strings.TrimSpace(c.CookieEncryptionSecretKey)

	if len(c.Cors.AllowOrigins) == 0 {
		return errors.New("rest cors allow_origins must not be empty")
	}

	for _, origin := range c.Cors.AllowOrigins {
		if origin == "*" {
			return errors.New("rest cors allow_origins must not contain '*' when cookie auth is enabled")
		}
	}

	switch c.CookieSameSite {
	case "lax", "strict", "none":
	default:
		return errors.New("rest cookie_same_site must be one of lax, strict, none")
	}

	if c.Development && c.CookieSameSite == "none" {
		return errors.New("rest cookie_same_site=none is invalid in development without secure cookies")
	}

	if c.CookieEncryptionSecretKey != "" && len(c.CookieEncryptionSecretKey) < 32 {
		return errors.New("rest cookie_encryption_secret_key must be at least 32 characters when set")
	}

	return nil
}

func normalizeStringSlice(values []string) []string {
	if len(values) == 0 {
		return nil
	}

	normalized := make([]string, 0, len(values))
	for _, value := range values {
		for _, part := range strings.Split(value, ",") {
			part = strings.TrimSpace(part)
			if part == "" {
				continue
			}
			normalized = append(normalized, part)
		}
	}

	return normalized
}

	return nil
}

func (a *Application) Stop(ctx context.Context) error {
	logger.Warn("Stopping application...")

	stopCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()

	if err := a.app.Stop(stopCtx); err != nil {
		return fmt.Errorf("failed to stop application gracefully: %w", err)
	}

	logger.Info("Application stopped successfully")

	return nil
}

